'use strict';
// Bundles scores/<section>/*.scrim and scores/cabinet.json into scores.js. Run with --check to verify the bundle is current.
const fs = require('node:fs');
const path = require('node:path');
const root = path.join(__dirname, '..');
const cabinet = JSON.parse(fs.readFileSync(path.join(root, 'scores', 'cabinet.json'), 'utf8'));
const tracks = [];
for (const section of cabinet.sections) {
  const dir = path.join(root, 'scores', section.id);
  const onDisk = fs.readdirSync(dir).filter(f => f.endsWith('.scrim'));
  const extra = onDisk.filter(f => !section.airs.includes(f));
  if (extra.length) throw new Error(`${section.id}: add ${extra.join(', ')} to scores/cabinet.json`);
  for (const file of section.airs) tracks.push({ file, section: section.id, text: fs.readFileSync(path.join(dir, file), 'utf8') });
}
const manifest = {
  mechanisms: cabinet.mechanisms,
  shelves: cabinet.shelves,
  sections: cabinet.sections.map(({ airs: _airs, ...section }) => section)
};
const out = '/* Generated by scripts/bundle-scores.js from scores/. Edit the .scrim files and scores/cabinet.json, not this bundle. */\n'
  + `window.ScrimCabinet = ${JSON.stringify(manifest)};\n`
  + `window.ScrimTracks = ${JSON.stringify(tracks)};\n`;
const target = path.join(root, 'scores.js');
if (process.argv.includes('--check')) {
  if (fs.readFileSync(target, 'utf8') !== out) throw new Error('scores.js is out of date. Run node scripts/bundle-scores.js');
} else fs.writeFileSync(target, out);
console.log(`Bundled ${tracks.length} airs in ${cabinet.sections.length} sections into scores.js`);
